const numb k171 = a[1];
const numb k043 = a[2];
const numb k832 = a[3];
const numb k0007 = a[4];
const numb k875 = a[5];
const numb k1003 = a[6];
const numb k112 = a[7];
const numb k0035 = a[8];
const numb k1745 = a[9];
const numb k280 = a[10];
const numb k069 = a[11];
const numb k181 = a[12];
const numb beta2 = numb(0.28867513459481287) + numb(1.6725140369678172e-17);
const numb beta3 = numb(0.23570226039551584) + numb(2.3915615546644207e-18);
const numb third = numb(1) / numb(3);
const ucmplx row2[] = {ucmplx(numb(0.5), -beta2), ucmplx(numb(0.5), beta2)};
const ucmplx row3[] = {ucmplx(third, -beta3), ucmplx(third, numb(0)), ucmplx(third, beta3)};

auto cd = [&](ucmplx* z, const ucmplx& fraction) {
    const ucmplx t = fraction * (h * numb(0.5));
    ucmplx& y1 = z[0];
    ucmplx& y2 = z[1];
    ucmplx& y3 = z[2];
    ucmplx& y4 = z[3];
    ucmplx& y5 = z[4];
    ucmplx& y6 = z[5];
    ucmplx& y7 = z[6];
    ucmplx& y8 = z[7];
    y1 = y1 + t * ((-k171) * y1 + (k043*y2 + k832*y3 + k0007));
    y2 = y2 + t * ((-k875) * y2 + (k171*y1));
    y3 = y3 + t * ((-k1003) * y3 + (k043*y4 + k0035*y5));
    y4 = y4 + t * ((-k112) * y4 + (k832*y2 + k171*y3));
    y5 = y5 + t * ((-k1745) * y5 + (k043*y6 + k043*y7));
    y6 = y6 + t * ((-k043 - k280*y8) * y6 + (k069*y4 + k171*y5 + k069*y7));
    y7 = y7 + t * ((-k181) * y7 + (k280*y6*y8));
    y8 = y8 + t * ((-k280*y6) * y8 + (k181*y7));
    y8 = (y8 + t * (k181*y7)) / (numb(1) - t * (-k280*y6));
    y7 = (y7 + t * (k280*y6*y8)) / (numb(1) - t * (-k181));
    y6 = (y6 + t * (k069*y4 + k171*y5 + k069*y7)) / (numb(1) - t * (-k043 - k280*y8));
    y5 = (y5 + t * (k043*y6 + k043*y7)) / (numb(1) - t * (-k1745));
    y4 = (y4 + t * (k832*y2 + k171*y3)) / (numb(1) - t * (-k112));
    y3 = (y3 + t * (k043*y4 + k0035*y5)) / (numb(1) - t * (-k1003));
    y2 = (y2 + t * (k171*y1)) / (numb(1) - t * (-k875));
    y1 = (y1 + t * (k043*y2 + k832*y3 + k0007)) / (numb(1) - t * (-k171));
};

ucmplx y2[8], y3[8];
for (int i = 0; i < 8; ++i) {
    y2[i] = ucmplx(X[i], numb(0));
    y3[i] = y2[i];
}
for (const auto& c : row2) cd(y2, c);
for (const auto& c : row3) cd(y3, c);
const numb w2 = -numb(1) / numb(5);
const numb w3 = numb(6) / numb(5);
for (int i = 0; i < 8; ++i) X[i] = w2 * y2[i].re + w3 * y3[i].re;
